/**
 * WxCC Widget Helper - Help Request Assistant
 * For agents who receive and respond to help requests from other agents
 * Now with multi-language support!
 */

import { Desktop } from "@wxcc-desktop/sdk";
import { sharedStyles } from "../shared/styles.js";

class WxccWidgetHelper extends HTMLElement {
    constructor() {
        super();
        this.attachShadow({ mode: 'open' });
        this.desktop = null;
        this.sdkReady = false;
        this.currentLanguage = 'en';   // Default language
        this.translations = {};         // Store translations
    }

    async connectedCallback() {
        // Load translations first
        const lang = this.getLanguage();
        await this.loadTranslations(lang);
        
        console.log('[WxCC Widget Helper] Widget connected');

        this.render();
        this.initSDK();
        
        let interaction = this.interactionData;
        
        // Read attributes from $STORE
        console.log('[WxCC Widget Helper] interaction data:', interaction);
        console.log('[WxCC Widget Helper] interaction data:', interaction.callAssociatedData);
        
        const emailBody = interaction.callAssociatedData.emailBody.value;
        console.log('[WxCC Widget Helper] email body:', emailBody);
        if (emailBody) {
            this.updateEmailBody(emailBody);
        }
        
        const emailSubject = interaction.callAssociatedData.emailSubject.value;
        console.log('[WxCC Widget Helper] email subject:', emailSubject);
        if (emailSubject){
            this.updateEmailSubject(emailSubject);
        }
        
        const agentNotes = interaction.callAssociatedData.notes.value;
        console.log('[WxCC Widget Helper] notes:', agentNotes);
        if (agentNotes) {
            this.updateAgentNotes(agentNotes);
        }
    }

    disconnectedCallback() {
        Desktop.agentContact.removeAllEventListeners();
    }

    /**
     * Get current language from Desktop SDK, attribute, or browser
     */
    getLanguage() {
        // Priority 1: Desktop SDK language
        try {
            if (Desktop?.config?.clientLocale) {
                const locale = Desktop.config.clientLocale;
                const lang = locale.split('-')[0]; // "en-US" -> "en"
                console.log('[WxCC Widget Helper] Language from Desktop SDK:', lang);
                return lang;
            }
        } catch (e) {
            // Desktop not ready yet
        }

        // Priority 2: Widget attribute
        const attrLang = this.getAttribute('language');
        if (attrLang) {
            console.log('[WxCC Widget Helper] Language from attribute:', attrLang);
            return attrLang;
        }

        // Priority 3: Browser language
        const browserLang = navigator.language.split('-')[0];
        console.log('[WxCC Widget Helper] Language from browser:', browserLang);
        return browserLang;
    }

    /**
     * Load translation file for specified language
     */
    async loadTranslations(lang) {
        try {
            // Try to load the specified language
            const response = await fetch(`./i18n/${lang}.json`);
            if (response.ok) {
                this.translations = await response.json();
                this.currentLanguage = lang;
                console.log(`[WxCC Widget Helper] ✅ Loaded translations for: ${lang}`);
                return;
            }
        } catch (error) {
            console.warn(`[WxCC Widget Helper] Could not load ${lang}.json:`, error);
        }

        // Fallback to English
        try {
            const fallback = await fetch('./i18n/en.json');
            this.translations = await fallback.json();
            this.currentLanguage = 'en';
            console.log('[WxCC Widget Helper] ⚠️ Falling back to English');
        } catch (error) {
            console.error('[WxCC Widget Helper] ❌ Failed to load any translations:', error);
            // Set minimal fallback
            this.translations = {
                labels: { subject: "Subject", body: "Body", agentNotes: "Agent Notes", suggestedAnswer: "Suggested Answer" },
                buttons: { sendSuggestion: "Send Suggestion" },
                defaults: { noSubject: "No subject", noBody: "No email body", noNotes: "No notes from requesting agent" }
            };
        }
    }

    /**
     * Translation helper - get translated string by path
     * @param {string} path - Path to translation key (e.g., "labels.subject")
     * @returns {string} Translated string
     */
    t(path) {
        const keys = path.split('.');
        let value = this.translations;
        
        for (const key of keys) {
            value = value?.[key];
            if (value === undefined) {
                console.warn(`[WxCC Widget Helper] Translation missing: ${path}`);
                return path; // Return key if translation not found
            }
        }
        
        return value;
    }

    initSDK() {
        console.log('[WxCC Widget Helper] Initializing SDK...');

        try {
            // Initialize Desktop SDK (synchronous call, no await)
            Desktop.config.init();
            
            this.desktop = Desktop;
            this.sdkReady = true;
            
            console.log('[WxCC Widget Helper] ✅ SDK Ready!');

            // Make Desktop globally accessible with debug method
            window.DesktopHelper = Desktop;
            Desktop.debugHelperWidget = () => this.debugDesktop();
            
            console.log('[WxCC Widget Helper] 💡 Desktop accessible via: window.DesktopHelper');
            console.log('[WxCC Widget Helper] 💡 Try: Desktop.debugHelperWidget() on the console!');
    
            // Setup Send Suggestion button
            this.setupSendSuggestionButton();
            
            console.log('[WxCC Widget Helper] ✅ Initialization complete');
            
        } catch (error) {
            console.error(`[WxCC Widget Helper] ${this.t('console.sdkError')}`, error);
            console.error('[WxCC Widget Helper] Error stack:', error.stack);
        }
    }
    
    render() {
        this.shadowRoot.innerHTML = `
            <style>${sharedStyles}</style>

            <!-- some styling here to add margins to the widget -->
            <style>
                :host {
                    display: block;
                    padding: 0 16px;  /* 16px left & right */
                }
            </style>
            
            <!-- Email Display Section -->
            <div class="email-section">
                <div class="email-field">
                    <div class="email-label">${this.t('labels.subject')}</div>
                    <div class="email-value email-subject" id="emailSubject">
                        ${this.t('defaults.noSubject')}
                    </div>
                </div>
                
                <div class="email-field">
                    <div class="email-label">${this.t('labels.body')}</div>
                    <div class="email-body" id="emailBody">
                        ${this.t('defaults.noBody')}
                    </div>
                </div>
            </div>
            
            <!-- Agent Notes Section (Read-only) -->
            <div class="notes-section">
                <div class="notes-label">${this.t('labels.agentNotes')}</div>
                <div class="notes-display" id="agentNotes">
                    ${this.t('defaults.noNotes')}
                </div>
            </div>
            
            <!-- Suggested Answer Section -->
            <div class="notes-section">
                <div class="notes-label">${this.t('labels.suggestedAnswer')}</div>
                <textarea class="notes-input large" id="suggestedAnswer" 
                    placeholder="${this.t('placeholders.provideSuggestion')}"></textarea>
            </div>
            
            <!-- Button Section -->
            <div class="button-section">
                <button class="help-button success" id="sendSuggestionBtn">
                    ${this.t('buttons.sendSuggestion')}
                </button>
                <div id="feedback" class="feedback"></div>
            </div>
        `;
    }
    
    updateEmailSubject(subject) {
        try {
            const el = this.shadowRoot?.getElementById('emailSubject');
            if (el) {
                el.textContent = subject || this.t('defaults.noSubject');
            } else {
                console.warn('[WxCC Widget Helper] emailSubject element not found in shadow DOM');
            }
        } catch (error) {
            console.error('[WxCC Widget Helper] ❌ Error in updateEmailSubject:', error);
        }
    }
    
    updateEmailBody(body) {
        try {            
            const el = this.shadowRoot?.getElementById('emailBody');
            if (el) {
                const cleanBody = JSON.parse('"' + body + '"');
                el.innerHTML = cleanBody || this.t('defaults.noBody');
            } else {
                console.warn('[WxCC Widget Helper] emailBody element not found in shadow DOM');
            }
        } catch (error) {
            console.error('[WxCC Widget Helper] ❌ Error in updateEmailBody:', error);
        }
    }
    
    updateAgentNotes(notes) {
        try {
            const el = this.shadowRoot?.getElementById('agentNotes');
            if (el) {
                el.textContent = notes || this.t('defaults.noNotes');
            } else {
                console.warn('[WxCC Widget Helper] agentNotes element not found in shadow DOM');
            }
        } catch (error) {
            console.error('[WxCC Widget Helper] ❌ Error in updateAgentNotes:', error);
        }
    }
    
    setupSendSuggestionButton() {
        try {
            const button = this.shadowRoot?.getElementById('sendSuggestionBtn');
            if (button) {
                button.addEventListener('click', () => this.handleSendSuggestion());
                console.log('[WxCC Widget Helper] ✅ Send Suggestion button listener attached');
            } else {
                console.warn('[WxCC Widget Helper] sendSuggestionBtn element not found in shadow DOM');
            }
        } catch (error) {
            console.error('[WxCC Widget Helper] ❌ Error in setupSendSuggestionButton:', error);
        }
    }
    
    async handleSendSuggestion() {
        console.log('[WxCC Widget Helper] 📤 Sending suggestion...');

        const button = this.shadowRoot?.getElementById('sendSuggestionBtn');
        
        // Get current data
        const suggestedAnswer = this.shadowRoot?.getElementById('suggestedAnswer')?.value;

        // Not used in this widget but keeping for reference
        const subject = this.shadowRoot?.getElementById('emailSubject')?.textContent;
        const body = this.shadowRoot?.getElementById('emailBody')?.textContent;
        const agentNotes = this.shadowRoot?.getElementById('agentNotes')?.textContent;
        
        // Validate suggested answer
        if (!suggestedAnswer || suggestedAnswer.trim() === '') {
            this.showFeedback('error', this.t('feedback.emptyAnswer'));
            return;
        }
        
        // Disable button during request
        if (button) button.disabled = true;
        
        try {
            console.log('[WxCC Widget Helper] 📤 Sending suggestion...');

            const customerEmail = this.interactionData.ani;

            const response = await fetch('https://hooks.uk.webexconnect.io/events/0C0K424T4I', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    "identity": customerEmail,
                    "textForJds": suggestedAnswer
                })
            });
            
            if (response.ok) {
                console.log('[WxCC Widget Helper] ✅ Suggestion sent successfully');
                this.showFeedback('success', this.t('feedback.suggestionSent'));
                
                // Clear the suggested answer field after successful send
                const textarea = this.shadowRoot?.getElementById('suggestedAnswer');
                if (textarea) textarea.value = '';
            } else {
                console.error('[WxCC Widget Helper] ❌ Server error:', response.status);
                this.showFeedback('error', this.t('feedback.serverError'));
            }
            
        } catch (error) {
            console.error('[WxCC Widget Helper] ❌ Error sending suggestion:', error);
            this.showFeedback('error', this.t('feedback.requestFailed'));
        } finally {
            // Re-enable button
            if (button) button.disabled = false;
        }
    }
    
    showFeedback(type, message) {
        try {
            const feedback = this.shadowRoot?.getElementById('feedback');
            if (feedback) {
                feedback.className = `feedback ${type}`;
                feedback.textContent = message;
                feedback.style.display = 'block';
                
                // Hide after 3 seconds
                setTimeout(() => {
                    feedback.style.display = 'none';
                }, 3000);
            } else {
                console.warn('[WxCC Widget Helper] feedback element not found in shadow DOM');
            }
        } catch (error) {
            console.error('[WxCC Widget Helper] ❌ Error in showFeedback:', error);
        }
    }
    
    debugDesktop() {
        if (!this.desktop) {
            console.warn('[WxCC Widget Helper] Desktop SDK not initialized yet');
            return;
        }

        console.group('🖥️ Desktop SDK Debug Info (Helper Widget)');
        
        console.log('1️⃣ All Modules:', Object.keys(this.desktop));
        
        console.group('2️⃣ config');
        console.log('Properties:', Object.keys(this.desktop.config));
        console.log('Methods:', Object.keys(this.desktop.config).filter(k => typeof this.desktop.config[k] === 'function'));
        console.log('Client Locale:', this.desktop.config.clientLocale);
        console.groupEnd();
        
        console.group('3️⃣ agentStateInfo');
        console.log('Properties:', Object.keys(this.desktop.agentStateInfo));
        console.log('Methods:', Object.keys(this.desktop.agentStateInfo).filter(k => typeof this.desktop.agentStateInfo[k] === 'function'));
        console.log('Current State:', this.desktop.agentStateInfo.latestData);
        console.log('Idle Codes:', this.desktop.agentStateInfo.idleCodes);
        console.groupEnd();
        
        console.group('4️⃣ agentContact');
        console.log('Properties:', Object.keys(this.desktop.agentContact));
        console.log('Methods:', Object.keys(this.desktop.agentContact).filter(k => typeof this.desktop.agentContact[k] === 'function'));
        console.log('Task Map:', this.desktop.agentContact.taskMap);
        console.log('Selected Task:', this.desktop.agentContact.taskSelected);
        console.groupEnd();
        
        console.group('5️⃣ actions');
        console.log('Properties:', Object.keys(this.desktop.actions));
        console.log('Methods:', Object.keys(this.desktop.actions).filter(k => typeof this.desktop.actions[k] === 'function'));
        console.groupEnd();
        
        if (this.desktop.dialer) {
            console.group('6️⃣ dialer');
            console.log('Properties:', Object.keys(this.desktop.dialer));
            console.log('Methods:', Object.keys(this.desktop.dialer).filter(k => typeof this.desktop.dialer[k] === 'function'));
            console.groupEnd();
        }
        
        if (this.desktop.screenpop) {
            console.group('7️⃣ screenpop');
            console.log('Properties:', Object.keys(this.desktop.screenpop));
            console.log('Methods:', Object.keys(this.desktop.screenpop).filter(k => typeof this.desktop.screenpop[k] === 'function'));
            console.groupEnd();
        }
        
        if (this.desktop.logger) {
            console.group('8️⃣ logger');
            console.log('Properties:', Object.keys(this.desktop.logger));
            console.log('Methods:', Object.keys(this.desktop.logger).filter(k => typeof this.desktop.logger[k] === 'function'));
            console.groupEnd();
        }
        
        console.groupEnd();
        
        // Make Desktop globally accessible for easy testing
        window.DesktopHelper = this.desktop;
        console.log('💡 Tip: Desktop is now available as window.DesktopHelper');
        console.log('💡 Try: Desktop.agentStateInfo.latestData');
        console.log('💡 Try: Desktop.config.clientLocale');
    }
    
}

customElements.define('wxcc-widget-helper', WxccWidgetHelper);
console.log('[WxCC Widget Helper] Widget loaded');